import Foundation
import LibSignalClient
import SignalProtos
import Testing
@testable import SignalCore

@Suite struct CallLinkEndorsementTests {
    // Generated by the pinned RingRTC zkgroup crate with CallLinkSecretParams::encrypt_uid,
    // root [0x42; 16] and ACIs [1; 16], [2; 16], [3; 16].
    private let ciphertexts = [
        "ANwXq5Hno/2Be0RB48OYNYuraxk1iNBa/KDeUqzMk6Fw6KAtQdCpiH7hsZ3qbrqf6Q3ga1n9frXMa33SptiauQQ=", "ANDs1WvwZyz7R4X7v6IA1ovY9VLZnXZBkwhojS7CikVArM3OtqrAlEaInh9TCu+AAJdybJxtQ21vexixNRlEbUA=", "AGqgKcGPEdfYG4JGpLBEUpQVkKoog6pU0BHDpQ+v4LYKrHvAaVWBb+60KT3m8aeRcJKV2KYoOqo5hBjA2xLihTQ=",
    ].compactMap { Data(base64Encoded: $0) }

    @Test func serverVerifiesOnlyExactAudienceAcrossIncrementalIssuance() throws {
        let params = CallLinkSecretParams.deriveFromRootKey(Data(repeating: 0x42, count: 16))
        let server = try ServerSecretParams.generate()
        var cache = try CallLinkEndorsements(params: params, server: server.getPublicParams())
        let now = Date(timeIntervalSince1970: 86_400 * 21_000)
        let expiry = now.addingTimeInterval(2 * 86_400)
        let keys = GroupSendDerivedKeyPair.forExpiration(expiry, params: server)
        let ciphers = try ciphertexts.map { try UuidCiphertext(contents: $0) }
        let ids = try ciphers.map { try params.decrypt($0) }
        #expect(ids.map(\.serviceIdBinary) == (1...3).map { Data(repeating: UInt8($0), count: 16) })
        func issue(_ subset: [Int], keys: GroupSendDerivedKeyPair) -> Data {
            GroupSendEndorsementsResponse.issue(groupMembers: subset.map { ciphers[$0] }, keyPair: keys).serialize()
        }
        let first = issue([0, 1], keys: keys), second = issue([2], keys: keys)
        let recipients = [ids[2].serviceIdBinary, ids[0].serviceIdBinary]
        cache.receive(first, members: Array(ciphertexts.prefix(2)), now: now)
        #expect(cache.endorsements(for: recipients, now: now) == nil)
        cache.receive(second, members: [ciphertexts[2]], now: now)
        let (date, proofs) = try #require(cache.endorsements(for: recipients, now: now))
        let full = try GroupSendFullToken(contents: cache.token(for: proofs, expiration: date, now: now))
        try full.verify(userIds: [ids[0], ids[2]], now: now, keyPair: keys)
        #expect(throws: (any Error).self) { try full.verify(userIds: [ids[0]], now: now, keyPair: keys) }
        #expect(throws: (any Error).self) { try full.verify(userIds: ids, now: now, keyPair: keys) }
        #expect(cache.endorsements(for: [recipients[0], recipients[0]], now: now) == nil)
        #expect(cache.endorsements(for: recipients, now: expiry) == nil)

        let other = try ServerSecretParams.generate()
        cache.receive(issue([2], keys: .forExpiration(expiry, params: other)), members: [ciphertexts[2]], now: now)
        #expect(cache.endorsements(for: recipients, now: now) == nil)
        cache.receive(second, members: [ciphertexts[2]], now: now)
        #expect(cache.endorsements(for: recipients, now: now) != nil)
        cache.receive(first, members: [ciphertexts[0], ciphertexts[0]], now: now)
        #expect(cache.endorsements(for: recipients, now: now) == nil)

        let newer = expiry.addingTimeInterval(86_400)
        cache.receive(issue([2], keys: .forExpiration(newer, params: server)), members: [ciphertexts[2]], now: now)
        cache.receive(first, members: Array(ciphertexts.prefix(2)), now: now)
        #expect(cache.endorsements(for: [ids[2].serviceIdBinary], now: now)?.0 == newer)
        #expect(cache.endorsements(for: recipients, now: now) == nil)
        var wrongLink = try CallLinkEndorsements(params: .deriveFromRootKey(Data(repeating: 77, count: 16)), server: server.getPublicParams())
        wrongLink.receive(first, members: Array(ciphertexts.prefix(2)), now: now)
        #expect(wrongLink.endorsements(for: [ids[0].serviceIdBinary], now: now) == nil)
    }

    @Test(.enabled(if: ProcessInfo.processInfo.environment["SEREIN_TEST_SFU_ENDORSEMENTS"] != nil))
    func verifiesUpstreamSFUAdmissionEndorsements() throws {
        struct Issuance: Decodable { let response: Data; let members: [Data] }
        let path = try #require(ProcessInfo.processInfo.environment["SEREIN_TEST_SFU_ENDORSEMENTS"])
        let updates = try JSONDecoder().decode([Issuance].self, from: Data(contentsOf: URL(fileURLWithPath: path)))
        let randomness = Randomness((71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71))
        let server = try ServerSecretParams.generate(randomness: randomness)
        var cache = try CallLinkEndorsements(params: .deriveFromRootKey(Data(repeating: 0x42, count: 16)), server: server.getPublicParams())
        for update in updates { cache.receive(update.response, members: update.members) }
        let admitted = [Data(repeating: 2, count: 16), Data(repeating: 4, count: 16)]
        let (expiration, proofs) = try #require(cache.endorsements(for: admitted))
        let token = try GroupSendFullToken(contents: cache.token(for: proofs, expiration: expiration))
        let keys = GroupSendDerivedKeyPair.forExpiration(expiration, params: server)
        try token.verify(userIds: admitted.map { try Aci.parseFrom(serviceIdBinary: $0) }, now: Date(), keyPair: keys)
        let denied = Data(repeating: 3, count: 16)
        #expect(cache.endorsements(for: admitted + [denied]) == nil)
        #expect(throws: (any Error).self) { try token.verify(userIds: [try Aci.parseFrom(serviceIdBinary: denied)], now: Date(), keyPair: keys) }
    }

    @Test func sealedSignalingReachesTwoMockSignalPeers() async throws {
        try await LinkedClient.with { c in
            struct Peer: Decodable { let aci: String }
            struct Delivered: Decodable { let data: Data; let envelopeType: String; let source: String }
            let bob = try await c.server.decode(Peer.self, "addAccount", ["name": "bob"])
            let names = ["alice", "bob"]
            let recipients = [c.aliceAci, bob.aci.lowercased()]
            let members = try await c.server.decode([Data].self, "callLinkCiphertexts", ["names": names])
            let server = try ServerSecretParams.generate()
            let params = CallLinkSecretParams.deriveFromRootKey(Data(repeating: 0x42, count: 16))
            let date = Date(timeIntervalSince1970: ((Date().timeIntervalSince1970 / 86_400).rounded(.down) + 2) * 86_400)
            let keys = GroupSendDerivedKeyPair.forExpiration(date, params: server)
            let response = try GroupSendEndorsementsResponse.issue(groupMembers: members.map { try UuidCiphertext(contents: $0) }, keyPair: keys)
            var cache = try CallLinkEndorsements(params: params, server: server.getPublicParams())
            cache.receive(response.serialize(), members: members)
            let acis = try recipients.map { try Aci.parseFrom(serviceIdString: $0) }
            let (expiry, endorsements) = try #require(cache.endorsements(for: acis.map(\.serviceIdBinary)))
            let token = try cache.token(for: endorsements, expiration: expiry)
            try GroupSendFullToken(contents: token).verify(userIds: acis, keyPair: keys)

            let opaque = Data([10, 4, 10, 2, 11, 22])
            var message = Signalservice_Content()
            message.callMessage.opaque.data = opaque
            let payload = OutgoingPayload(content: message, timestamp: TestClock.next(), contentHint: .default, urgent: false)
            let gone = try await c.messenger.groupSender.sendCallLink(payload, recipients: recipients, token: token, expiration: expiry, distributionId: UUID(), scope: {})
            #expect(gone.isEmpty)
            for name in names {
                let delivered = try await c.server.decode(Delivered.self, "waitForOpaqueCall", ["account": name])
                #expect(delivered.data == opaque && delivered.source == c.account.aci && delivered.envelopeType == "SealedSender")
            }
        }
    }

    @Test func ephemeralSignalSenderKeyDecryptsOnlyItsSinglePayload() throws {
        let signingKey = IdentityKeyPair.generate()
        let certificate = try ServerCertificate(keyId: 1, publicKey: signingKey.publicKey, trustRoot: IdentityKeyPair.generate().privateKey)
        let address = try ProtocolAddress(name: "01010101-0101-0101-0101-010101010101", deviceId: 1)
        let sender = try SealedSenderAddress(e164: nil, uuidString: address.name, deviceId: 1)
        let cert = try SenderCertificate(sender: sender, publicKey: IdentityKeyPair.generate().publicKey, expiration: 172800,
                                         signerCertificate: certificate, signerKey: signingKey.privateKey)
        let plaintext = Data([0x0a, 2, 8, 1])
        let distributionId = UUID()
        let first = try GroupSender.callLinkEnvelope(plaintext: plaintext, local: address, certificate: cert, hint: .default, distributionId: distributionId)
        let second = try GroupSender.callLinkEnvelope(plaintext: plaintext, local: address, certificate: cert, hint: .default, distributionId: distributionId)
        let receiver = InMemorySignalProtocolStore()
        let key = try SenderKeyDistributionMessage(bytes: first.0)
        try processSenderKeyDistributionMessage(key, from: address, store: receiver, context: NullContext())
        let message = try UnidentifiedSenderMessageContent(bytes: first.1)
        #expect(try groupDecrypt(message.contents, from: address, store: receiver, context: NullContext()) == plaintext)
        let otherMessage = try UnidentifiedSenderMessageContent(bytes: second.1)
        #expect(throws: (any Error).self) { try groupDecrypt(otherMessage.contents, from: address, store: receiver, context: NullContext()) }
    }
}
